'use strict'

import { SPRITE_TEXT_COLOR_WHITE, SPRITE_TEXT_HEIGHT, SPRITE_TEXT_WIDTH, TILE_WIDTH, TILE_HEIGHT, NES_PIXEL } from '../constant'
import textManager from '../service/text-manager'
import clock from '../service/clock'
import { flashImage } from './enemies/common'

class Character {
  constructor (name, column, line, x, y, width, height, sprite, text) {
    this.name = name
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.width = width
    this.height = height
    this.sprite = sprite
    this.text = text
    // What he says when Link comes in; text changes when he answers (pay_to_talk caves)
    this.defaultText = text
    this.displayedText = ''
    this.enabled = true
  }

  init () {
    this.enabled = true
    this.text = this.defaultText
  }

  // Says something else (written out again by the Dialog transition)
  say (text) {
    this.text = text
    this.displayedText = ''
  }

  reset () {
    this.displayedText = ''
  }

  hasStoppedTalking () {
    return this.displayedText === this.text
  }

  draw (context) {
    this.vanishDrawingCalled = true
    if (!this.enabled) {
      return
    }

    // People stand still in the caves, as in the original: always the first image (the moblin of the
    // secret cave shares the walking sprite of the enemies)
    // Struck (an old man of a level), in the palettes of the ROM a while
    const image = flashImage(this.sprite.images?.[0] ?? this.sprite, this.flashSteps, this.flashType)
    image.draw(context, this.x, this.y, this.width, this.height)
    if (this.textPlace) {
      this.drawPlacedText(context)
      return
    }
    textManager.draw(context, this.text, SPRITE_TEXT_COLOR_WHITE, this.x - 4.5 * TILE_WIDTH - TILE_WIDTH / 2, this.y - SPRITE_TEXT_HEIGHT * 3, 11 * TILE_WIDTH, SPRITE_TEXT_HEIGHT * 3, 'middle', this.displayedText.length)
  }

  // Each line from its column, as the ROM writes it (textPlace: { top, columns }, in NES pixels and characters from
  // the top left of the room)
  drawPlacedText (context) {
    const left = this.x - this.column * TILE_WIDTH
    const top = this.y - this.line * TILE_HEIGHT + this.textPlace.top * NES_PIXEL
    let shown = this.displayedText.length
    this.text.split('\n').forEach((line, i) => {
      const part = line.slice(0, Math.max(0, shown))
      shown -= line.length + 1
      textManager.drawLine(context, part, SPRITE_TEXT_COLOR_WHITE, left + this.textPlace.columns[i] * SPRITE_TEXT_WIDTH, top + i * SPRITE_TEXT_HEIGHT)
    })
  }

  vanish (timeout) {
    const self = this
    self.displayedText = ''
    const timer = clock.repeat(() => {
      if (self.vanishDrawingCalled) {
        self.enabled = !self.enabled
        self.vanishDrawingCalled = false
      }
    }, 5)
    clock.delay(() => {
      timer.cancel()
      self.enabled = false
    }, timeout)
  }
}

export { Character }
