'use strict'

import Game from './game'
import { Debug } from './debug'
import { Controls } from './controls'
import { TitleScreen } from './title-screen'
import io from '../utils/io'
import resource from '../resource'
import soundManager from '../service/sound-manager'
import worldManager from '../service/world-manager'
import clock from '../service/clock'
import { PATH_DATA_GAME, FILE_TYPE_LOZ, GAME_INTERVAL_PROCESS, GAME_INTERVAL_INPUT } from '../constant'
import { Display } from './display'
import { TouchControls } from './touch-controls'

let game
let gameData
let processTimer
let processInputTimer
let lastFrameTime
const canvas = document.querySelector('#loz-canvas')
// Opaque (the page is black). Not desynchronized: the browser would show the canvas while a frame is being drawn
// (cleared, then half drawn), and the game would flicker
const context = canvas.getContext('2d', { alpha: false })

canvas.onload = () => { canvas.focus() }
// Installed as an app (manifest.webmanifest), the page keeps its files to be played without network (public/sw.js)
navigator.serviceWorker?.register('sw.js').catch(e => console.warn('Service worker: ' + e.message))
// The pad of the touch screens, then the size of the screen (around the pad) and graphics pack, chosen in the page
const touch = new TouchControls(document.querySelector('input#play-sounds'), document.querySelector('form.game-controls'))
const display = new Display(canvas, context, document.querySelector('select#control-screen-size'), document.querySelector('select#control-graphics'), touch, document.querySelector('input#control-detailed-map'))

const debug = new Debug(
  document.querySelector('input#control-blocking-zones'),
  document.querySelector('input#control-blocking-zones-color'),
  document.querySelector('input#control-rupees'),
  document.querySelector('input#control-rupees-submit'),
  document.querySelector('input#control-keys'),
  document.querySelector('input#control-keys-submit'),
  document.querySelector('input#control-bombs'),
  document.querySelector('input#control-bombs-submit'),
  document.querySelector('input#control-convert-file-to-loz'),
  document.querySelector('input#control-all-items')
)
// The key bindings of the page (the object keeps itself up to date)
// eslint-disable-next-line no-new
new Controls(document.querySelector('#control-key-bindings'), document.querySelector('#control-key-bindings-reset'), canvas)
soundManager.initContext()
soundManager.initEvents(document.querySelector('input#play-sounds'), document.querySelector('input#control-volume'))
await resource.loadAll()
touch.init()
await display.init()

// The page opens on the title screen; Start begins a game on the current data (default or imported)
const titleScreen = new TitleScreen(() => loadGame(gameData))

function showTitle () {
  game?.stop()
  game = undefined
  window.game = undefined
  clock.reset()
  titleScreen.show()
}

async function loadGame (data) {
  // A new game starts from scratch: the previous one stops, and its timers (steps, animations,
  // transitions in progress) are dropped
  game?.stop()
  clock.reset()
  titleScreen.hide()
  gameData = data

  worldManager.createMaps(gameData)

  game = new Game()
  debug.setGame(game)
  window.game = game // Reachable from the console for debugging
  game.onRetry = showTitle

  // Fixed time steps on the game clock, whatever the display frame rate
  // (input first: timers due at the same time fire in creation order, so a key is played in the same step)
  processInputTimer?.cancel()
  processInputTimer = clock.repeat(() => game.processInput(), GAME_INTERVAL_INPUT)
  processTimer?.cancel()
  processTimer = clock.repeat(() => game.process(), GAME_INTERVAL_PROCESS)

  game.start()
}

// One iteration per display frame: advance the clock (runs due steps and animations), then draw
function frame (time) {
  if (lastFrameTime !== undefined) {
    clock.tick(time - lastFrameTime)
  }
  lastFrameTime = time
  // Drawn in display pixels of the game, the canvas scaled to its size
  display.prepare()
  const { width, height } = display
  if (titleScreen.visible) {
    titleScreen.draw(context, width, height)
  } else if (game) {
    game.draw(context, 0, 0, width, height)
    debug.draw(context, 0, 0, width, height)
  }
  window.requestAnimationFrame(frame)
}

gameData = await io.fetchRemoteFile(PATH_DATA_GAME)
showTitle()
window.requestAnimationFrame(frame)

document.querySelector('input#control-import-game').addEventListener('click', async (e) => {
  e.preventDefault()
  // An imported game starts right away
  loadGame(await io.openFile(FILE_TYPE_LOZ))
})
